async function loadWholesaleReturn(id) {
  const [ret2] = await db.select().from(wholesaleReturnsTable).where(eq(wholesaleReturnsTable.id, id));
  if (!ret2) return null;
  const lines = await db.select().from(wholesaleReturnLinesTable).where(eq(wholesaleReturnLinesTable.returnId, id)).orderBy(wholesaleReturnLinesTable.id);
  return { ret: ret2, lines };
}

